const BRAND_MATCH = [['netflix', /netflix/i], ['youtubemusic', /youtube music/i], ['youtube', /youtube/i], ['spotify', /spotify/i], ['applemusic', /apple ?music|AppleInc\.AppleMusic/i], ['itunes', /itunes/i], ['primevideo', /prime video|primevideo/i], ['amazonmusic', /amazon ?music/i], ['twitch', /twitch/i], ['soundcloud', /soundcloud/i], ['tidal', /tidal/i], ['crunchyroll', /crunchyroll/i], ['plex', /plex/i], ['kodi', /kodi/i], ['vlc', /^vlc$|vlc media player|VideoLAN/i], ['winamp', /winamp/i], ['foobar2000', /foobar2000/i], ['mpv', /^mpv/i], ['claude', /^claude/i], ['openai', /^(codex|openai|chatgpt)/i], ['gemini', /^gemini/i], ['copilot', /copilot/i], ['zoom', /zoom/i], ['discord', /discord/i], ['meet', /google meet|meet\.google/i], ['chrome', /chrome/i], ['firefox', /firefox/i], ['brave', /brave/i], ['opera', /opera/i], ['vivaldi', /vivaldi/i]];
// Which brand something is: checks each text (site text first, then the app) against the list.
function brandOf(...texts) {
  for (const t of texts) { if (!t) continue; for (const [id, re] of BRAND_MATCH) if (re.test(String(t))) return id; }
  return '';
}
// The brand's logo as an SVG, in white (or a colour) on transparent.
// Where a brand's real icon isn't a flat colour, match the real one: tile colour and logo colour (or gradient).
